 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    q = (y + dy, x + dx)
                    if 0 <= q[0] < h and 0 <= q[1] < w and grid[q[0]][q[1]] == 5 and q not in seen:
                        seen.add(q)
                        stack.append(q)
            components.append(comp)

    for comp in components:
        r0 = min(r for r, c in comp)
        r1 = max(r for r, c in comp)
        c0 = min(c for r, c in comp)
        c1 = max(c for r, c in comp)
        # The figures are open rectangular frames: fill their cavity and top opening.
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if grid[r][c] == 0:
                    out[r][c] = 2
        # The opening sends a horizontal beam left from the row just above the frame.
        if r0 > 0:
            for c in range(c0):
                out[r0 - 1][c] = 2
            # Extend to the top opening's column (the only missing top-edge cell).
            top_zeros = [c for c in range(c0, c1 + 1) if grid[r0][c] == 0]
            if top_zeros:
                gap = top_zeros[0]
                for c in range(c0, gap + 1):
                    out[r0 - 1][c] = 2
    return out
